-- n8n node: Execute a SQL query in Postgres2
-- Query parameters are in the workflow; n8n expressions are not standalone SQL.
WITH p AS (SELECT $1::jsonb j), idx AS (SELECT subject_id FROM mimiciv_hosp.admissions WHERE hadm_id=(SELECT (j->>'hadm_id')::int FROM p)), matched AS (
 SELECT DISTINCT v.hadm_id,NULL::int AS h,v.outcome_mortality_30d AS m,v.outcome_readmission_30d AS r,v.outcome_los_hours AS los
 FROM mimiciv.agent_pharmacy_v2 v JOIN mimiciv_hosp.admissions a ON a.hadm_id=v.hadm_id CROSS JOIN p CROSS JOIN idx
 WHERE a.subject_id<>idx.subject_id AND (p.j->'matching_features'->>'med_count')::int>0 AND (p.j->'matching_features'->>'med_count' IS NULL OR v.total_med_count BETWEEN (p.j->'matching_features'->>'med_count')::numeric-5 AND (p.j->'matching_features'->>'med_count')::numeric+5) AND (p.j->'matching_features'->>'has_sepsis' IS NULL OR v.has_sepsis_treatment=(p.j->'matching_features'->>'has_sepsis')::boolean) AND (p.j->'matching_features'->>'has_palliative' IS NULL OR v.has_palliative_pattern=(p.j->'matching_features'->>'has_palliative')::boolean) AND (p.j->'matching_features'->>'has_broad_abx' IS NULL OR v.has_broad_spectrum_abx=(p.j->'matching_features'->>'has_broad_abx')::boolean) AND (p.j->'matching_features'->>'has_pressors' IS NULL OR v.has_pressors=(p.j->'matching_features'->>'has_pressors')::boolean) AND (p.j->'matching_features'->>'has_sedatives' IS NULL OR v.has_sedatives=(p.j->'matching_features'->>'has_sedatives')::boolean) AND (p.j->'matching_features'->>'has_anticoagulants' IS NULL OR v.has_anticoagulants=(p.j->'matching_features'->>'has_anticoagulants')::boolean) AND (p.j->'matching_features'->>'has_diuretics' IS NULL OR v.has_diuretics=(p.j->'matching_features'->>'has_diuretics')::boolean)
), agg AS (SELECT count(*) AS n,jsonb_build_object('denominator',count(h) FILTER(WHERE h IN(0,1)),'events',count(*) FILTER(WHERE h=1),'value',avg(h) FILTER(WHERE h IN(0,1))) AS h,jsonb_build_object('denominator',count(m) FILTER(WHERE m IN(0,1)),'events',count(*) FILTER(WHERE m=1),'value',avg(m) FILTER(WHERE m IN(0,1))) AS m,jsonb_build_object('denominator',count(r) FILTER(WHERE r IN(0,1)),'events',count(*) FILTER(WHERE r=1),'value',avg(r) FILTER(WHERE r IN(0,1))) AS r,jsonb_build_object('denominator',count(los) FILTER(WHERE los>=0),'events',NULL,'value',avg(los/24.0) FILTER(WHERE los>=0)) AS l FROM matched)
SELECT jsonb_build_object('contract_version','mas_original_severity_v3','case_id',p.j->>'case_id','role','pharmacy','similar_patients_found',agg.n,'cohort_unit','admissions','same_patient_excluded',true,'matching_features',p.j->'matching_features','probability_unit','fraction','los_unit','days','los_statistic','mean','mortality_30d_origin','discharge','endpoints',jsonb_build_object('in_hospital_mortality',agg.h,'mortality_30d',agg.m,'readmission_30d',agg.r,'los_days',agg.l)) AS cohort FROM p CROSS JOIN agg;
